-- Мапа повітряних тривог по областях України (ubilling.net.ua/aerialalerts, без ключа API).
-- Дані оновлюються кожні 30 с і в застосунку, і на шпалерах (потрібен Wi-Fi та свіжа Keira),
-- останній стан зберігається в alerts.txt.
-- Застосунок: A — оновити, START — вихід.

lilka.fullscreen = false

