    { name = "м. Київ", cx = 123, cy = 42, rects = "B4AoADABB9AoACABB3ApAJABB3AqAIABB5ArAGABB6AsAFABB7AtADABB8AuABAC" },
    { name = "Севастополь", cx = 166, cy = 171, rects = "CjClACABCjCmAEABCjCnAGABCjCoAHABCiCpAIABChCqAKACChCsALADChCvAMABCiCwAKABCjCxAIAB" },
}
local SILHOUETTE = ""
-- MAP END

local sin, floor = math.sin, math.floor
local function min(a, b) if a < b then return a end return b end
local function max(a, b) if a > b then return a end return b end
local function clamp(x, a, b) return min(b, max(a, x)) end
local function rgb(r, g, b) return display.color565(floor(clamp(r, 0, 255)), floor(clamp(g, 0, 255)), floor(clamp(b, 0, 255))) end
local function mix(a, b, k) return { a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k, a[3] + (b[3] - a[3]) * k } end

local W, H
local OX, OY
local t = 0
local next_fetch = 1
local alerts, at = {}, nil -- alerts[i] = true, якщо в області i тривога
local ended = {}           -- ended[i] = час відбою, щоб показати його кілька хвилин
local status
local home

local BG = { 10, 12, 20 }
local CALM = { 38, 58, 84 }
local ALERT = { 225, 45, 45 }
local CLEAR = { 60, 200, 120 }

-- Прямокутники закодовано по 2 символи на число (base64)
local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function decode(s)
    local idx = {}
    for i = 1, #B64 do idx[B64:byte(i)] = i - 1 end
    local out = {}
    for i = 1, #s, 2 do out[#out + 1] = idx[s:byte(i)] * 64 + idx[s:byte(i + 1)] end
    return out
end

local CRIMEA, SEVASTOPOL
local function by_name(name)
    for i, r in ipairs(REGIONS) do
        if r.name == name then return i end
    end
end

local function save()
    local bits = {}
    for i = 1, #REGIONS do bits[i] = alerts[i] and "1" or "0" end
    pcall(resources.write_file, CACHE, "at=" .. at .. "\nalerts=" .. table.concat(bits))
end

local function load()
    local ok, text = pcall(resources.read_file, CACHE)
    if not ok or not text then return end
    local a, bits = text:match("at=(%d+)"), text:match("alerts=([01]+)")
    if not (a and bits and #bits == #REGIONS) then return end
    at = tonumber(a)
    for i = 1, #REGIONS do alerts[i] = bits:sub(i, i) == "1" end
end

local function apply(now)
    -- В API немає Криму окремо, тож він бере стан Севастополя
    now[CRIMEA] = now[SEVASTOPOL]
    for i = 1, #REGIONS do
        if alerts[i] and not now[i] and at then ended[i] = os.time() end
        if now[i] then ended[i] = nil end
        alerts[i] = now[i] or false
    end
    at = os.time()
    save()
end

local function fetch()
    if not (http and wifi) or wifi.get_status() ~= 3 then
        status = "Wi-Fi не під'єднано"
        return
    end
    collectgarbage()
    local ok, res = pcall(http.execute, { url = URL })
    if not (ok and res.code == 200 and res.response) then
        status = "Не вдалося завантажити"
        return
    end
    local now, n = {}, 0
    for key, v in res.response:gmatch('"([^"]+)":{"alertnow":(%a+)') do
        local name = key:gsub("\\u(%x%x%x%x)", function(h) return utf8.char(tonumber(h, 16)) end)
        local i = by_name(name)
        if i then now[i] = v == "true"; n = n + 1 end
    end
    if n < 20 then
        status = "Незрозуміла відповідь"
        return
    end
    apply(now)
    status = nil
end

function lilka.init()
    W, H = display.width, display.height
    -- Застосунок стартує на весь екран, тож display.height = 240 навіть з fullscreen = false
    if not lilka.fullscreen and H > 216 then H = H - 24 end
    OX, OY = floor((W - MAP_W) / 2), H - MAP_H - 4
    for _, r in ipairs(REGIONS) do r.rects = decode(r.rects) end
    SILHOUETTE = decode(SILHOUETTE)
    CRIMEA, SEVASTOPOL = by_name("АР Крим"), by_name("Севастополь")
    home = by_name(HOME)
    load()
end

function lilka.update(delta)
    t = t + delta
    next_fetch = next_fetch - delta
    if next_fetch <= 0 then
        next_fetch = REFRESH
        fetch()
    end
    if controller then
        local st = controller.get_state()
        if st.a.just_pressed then next_fetch = REFRESH; fetch() end
        if st.start.just_pressed then util.exit() end
    end
end

local function text(x, y, s, c, font)
    display.set_font(font or "6x13")
    display.set_text_size(1)
    display.set_text_color(c)
    display.set_cursor(floor(x), floor(y))
    display.print(s)
end

local function fill(rects, c)
    for i = 1, #rects, 4 do
        display.fill_rect(OX + rects[i], OY + rects[i + 1], rects[i + 2], rects[i + 3], c)
    end
end

local function hm(ts)
    local d = os.date("*t", ts)
    return string.format("%02d:%02d", d.hour, d.min)
end

function lilka.draw()
    display.fill_screen(rgb(BG[1], BG[2], BG[3]))
    local now = os.time()
    local stale = not at or now - at > STALE
    local hx, hy = home and REGIONS[home].cx or 0, home and REGIONS[home].cy or 0

    fill(SILHOUETTE, rgb(4, 6, 10))
    local count = 0
    for i, r in ipairs(REGIONS) do
        local c = CALM
        if alerts[i] then
            if i ~= CRIMEA then count = count + 1 end
            -- Хвиля пульсації розходиться від вашої області
            local d = ((r.cx - hx) ^ 2 + (r.cy - hy) ^ 2) ^ 0.5
            c = mix(ALERT, { 120, 20, 28 }, 0.5 + 0.5 * sin(t * 3 - d * 0.04))
        elseif ended[i] and now - ended[i] < 600 then
            c = mix(CLEAR, CALM, (now - ended[i]) / 600)
        end
        if stale then c = mix(c, { 70, 70, 76 }, 0.6) end
        fill(r.rects, rgb(c[1], c[2], c[3]))
    end

    if home then
        local rad = 4 + (t * 6) % 10
        local k = 1 - (rad - 4) / 10
        local hc = alerts[home] and ALERT or CLEAR
        display.draw_circle(OX + hx, OY + hy, floor(rad), rgb(hc[1] * k + BG[1], hc[2] * k + BG[2], hc[3] * k + BG[3]))
        display.fill_circle(OX + hx, OY + hy, 2, rgb(255, 255, 255))
    end

    local white, grey = rgb(240, 244, 255), rgb(140, 150, 175)
    text(8, 16, "Повітряна тривога", white, "8x13")
    text(W - 38, 16, hm(now), white, "8x13")
    if at then
        local line = count > 0 and ("Тривога в " .. count .. " обл.") or "Тривог немає"
        text(8, 30, line, count > 0 and rgb(255, 110, 100) or rgb(110, 220, 150), "6x12")
        if home then
            local hn = HOME:gsub(" область", " обл."):gsub("^м%. ", "")
            local hs = hn .. ": " .. (alerts[home] and "тривога" or "відбій")
            text(8, H - 30, hs, alerts[home] and rgb(255, 120, 110) or rgb(120, 225, 160), "6x12")
        end
        text(8, H - 16, (stale and "застаріло, " or "") .. "о " .. hm(at), grey, "6x12")
    else
        text(8, 30, "Немає даних", white, "6x12")
    end
    if status and (controller or not at) then text(8, H - 4, status, rgb(255, 120, 100), "6x12") end
end
